"use client";

import { createContext, useCallback, useContext, useEffect, useId, useMemo, useRef, useState } from "react";
import type { CSSProperties, ReactNode } from "react";
import * as Popover from "@radix-ui/react-popover";
import { motion, useReducedMotion } from "motion/react";
import { ArrowUpRight } from "lucide-react";
import { motionTokens } from "@/lib/motion-tokens";
import styles from "./citations.module.css";

export interface CitationSource {
  /** Stable id that `<Citation source>` refers to. */
  id: string;
  /** Title of the page or document. */
  title: string;
  /** Address the source opens. */
  url: string;
  /** Name of the site. Defaults to the host of `url`. */
  site?: string;
  /** Short passage or summary that supports the claim. */
  snippet?: string;
  /** Publication date or year, as it should be shown. */
  date?: string;
}

export interface CitationsProps {
  /** Every source that can be cited, in the order they are numbered. */
  sources: CitationSource[];
  /** The text with `<Citation>` chips inside it, and usually a `<CitationSources>` list after it. */
  children: ReactNode;
  /** Id of the highlighted source (controlled). */
  activeId?: string | null;
  /** Called when hover, focus or an open card changes the highlighted source. */
  onActiveIdChange?: (id: string | null) => void;
  /** Render the source cards inside this element and limit collisions to it (used by the demo stages). */
  container?: HTMLElement | null;
  /** Class name added to the root element. */
  className?: string;
}

export interface CitationProps {
  /** Id of the source this chip cites. */
  source: string;
  /** Starts with this chip's card pinned open, for previews. Focus stays where it is until a person uses the card. */
  defaultOpen?: boolean;
  /** Class name added to the chip. */
  className?: string;
}

export interface CitationSourcesProps {
  /** Heading above the list. */
  title?: string;
  /** Class name added to the list wrapper. */
  className?: string;
}

interface CitationsContextValue {
  sources: CitationSource[];
  active: string | null;
  setActive: (id: string | null) => void;
  scope: string;
  container: HTMLElement | null;
}

const CitationsContext = createContext<CitationsContextValue | null>(null);
/** The letter marks rotate through the categorical tones, so neighbours in the list never share a color. */
const tones = ["sky", "orchid", "amber", "teal", "violet", "rose", "green"] as const;
const toneOf = (index: number) => `var(--tone-${tones[index % tones.length]})`;

function hostOf(url: string) {
  try { return new URL(url).hostname.replace(/^www\./, ""); } catch { return url; }
}

function useCitations(part: string) {
  const context = useContext(CitationsContext);
  if (!context) throw new Error(`<${part}> must be rendered inside <Citations>.`);
  return context;
}

function SiteMark({ site, index }: { site: string; index: number }) {
  return <span className={styles.mark} style={{ "--tone": toneOf(index) } as CSSProperties} aria-hidden="true">{site.charAt(0).toUpperCase()}</span>;
}

/**
 * Groups an answer with its sources. Inside it, `<Citation>` is a numbered chip that opens a card with the source, and `<CitationSources>`
 * lists them all. The parts share one highlight: pointing at a chip marks its row in the list, and pointing at a row lights up its chips.
 */
export function Citations({ sources, children, activeId, onActiveIdChange, container = null, className }: CitationsProps) {
  const scope = useId();
  const [internal, setInternal] = useState<string | null>(null);
  const active = activeId === undefined ? internal : activeId;
  const setActive = useCallback((id: string | null) => { setInternal(id); onActiveIdChange?.(id); }, [onActiveIdChange]);
  const value = useMemo(() => ({ sources, active, setActive, scope, container }), [sources, active, setActive, scope, container]);
  return (
    <CitationsContext.Provider value={value}>
      <div className={[styles.root, className].filter(Boolean).join(" ")}>{children}</div>
    </CitationsContext.Provider>
  );
}

/** A numbered chip for the middle of a sentence. Hover, focus plus Enter, or a tap opens a card with the source; a click pins it open. */
export function Citation({ source, defaultOpen = false, className }: CitationProps) {
  const { sources, active, setActive, container } = useCitations("Citation");
  const index = sources.findIndex(entry => entry.id === source);
  const entry = sources[index];
  const [open, setOpen] = useState(defaultOpen);
  /** A card that starts pinned does not pull focus in on its first frame. */
  const quiet = useRef(defaultOpen);
  const startOpen = useRef(defaultOpen);
  useEffect(() => { if (startOpen.current && entry) setActive(entry.id); }, [entry, setActive]);
  // A card opened by hovering closes when the pointer leaves and never takes focus; one opened by click or keyboard behaves like a popover.
  const byHover = useRef(false);
  const skipFocusReturn = useRef(false);
  const timer = useRef<number | undefined>(undefined);
  useEffect(() => () => window.clearTimeout(timer.current), []);
  if (!entry) return null;
  const site = entry.site ?? hostOf(entry.url);

  const change = (next: boolean) => {
    window.clearTimeout(timer.current);
    setOpen(next);
    setActive(next ? entry.id : null);
    if (!next) { skipFocusReturn.current = byHover.current; byHover.current = false; }
  };
  const hover = (next: boolean) => {
    window.clearTimeout(timer.current);
    if (next && open) return;
    if (!next && !byHover.current) return;
    timer.current = window.setTimeout(() => { if (next) byHover.current = true; change(next); }, next ? 110 : 170);
  };

  return (
    <Popover.Root open={open} onOpenChange={change}>
      {/* A word joiner inside a no-wrap span keeps the chip on the same line as the word it follows. */}
      <span className={styles.joint}>
        {"\u2060"}
        <Popover.Trigger asChild>
          <button
            type="button"
            className={[styles.chip, className].filter(Boolean).join(" ")}
            data-active={active === entry.id || undefined}
            aria-label={`Source ${index + 1}: ${entry.title}`}
            onPointerEnter={event => { if (event.pointerType === "mouse") hover(true); }}
            onPointerLeave={event => { if (event.pointerType === "mouse") hover(false); }}
            onClick={event => {
              // The card is already showing from the hover: the click pins it instead of toggling it shut.
              if (open && byHover.current) { event.preventDefault(); byHover.current = false; window.clearTimeout(timer.current); }
            }}
          >
            {index + 1}
          </button>
        </Popover.Trigger>
      </span>
      <Popover.Portal container={container ?? undefined}>
        <Popover.Content
          className={styles.card}
          side="top"
          align="center"
          sideOffset={8}
          collisionPadding={12}
          collisionBoundary={container ?? undefined}
          aria-label={`Source ${index + 1}`}
          onOpenAutoFocus={event => { if (byHover.current || quiet.current) { quiet.current = false; event.preventDefault(); } }}
          onCloseAutoFocus={event => { if (skipFocusReturn.current) event.preventDefault(); }}
          onPointerEnter={() => window.clearTimeout(timer.current)}
          onPointerLeave={event => { if (event.pointerType === "mouse") hover(false); }}
        >
          <div className={styles.cardSite}>
            <SiteMark site={site} index={index} />
            <span className={styles.cardHost}>{site}</span>
            {entry.date ? <span className={styles.cardDate}>{entry.date}</span> : null}
            <span className={styles.cardNumber} aria-hidden="true">{index + 1}</span>
          </div>
          <a className={styles.cardTitle} href={entry.url} target="_blank" rel="noreferrer noopener">
            {entry.title}
            <ArrowUpRight size={14} aria-hidden="true" />
          </a>
          {entry.snippet ? <p className={styles.cardSnippet}>{entry.snippet}</p> : null}
        </Popover.Content>
      </Popover.Portal>
    </Popover.Root>
  );
}

/** The numbered list of every source. One highlight glides to the row under the pointer or keyboard focus, or to the source whose chip is active. */
export function CitationSources({ title = "Sources", className }: CitationSourcesProps) {
  const { sources, active, setActive, scope } = useCitations("CitationSources");
  const reduceMotion = useReducedMotion() ?? false;
  const headingId = useId();
  return (
    <section className={[styles.sources, className].filter(Boolean).join(" ")} aria-labelledby={headingId}>
      <h3 id={headingId} className={styles.sourcesTitle}>{title}<span className={styles.sourcesCount}>{sources.length}</span></h3>
      <ol className={styles.list} onPointerLeave={() => setActive(null)}>
        {sources.map((entry, index) => {
          const site = entry.site ?? hostOf(entry.url);
          return (
            <motion.li
              key={entry.id}
              className={styles.item}
              initial={reduceMotion ? false : { opacity: 0, y: 8 }}
              animate={{ opacity: 1, y: 0 }}
              transition={reduceMotion ? { duration: 0 } : { ...motionTokens.spring.gentle, delay: 0.08 + index * motionTokens.stagger.item * 1.6 }}
            >
              {active === entry.id ? <motion.span layoutId={`${scope}-highlight`} className={styles.highlight} transition={reduceMotion ? { duration: 0 } : motionTokens.spring.morph} /> : null}
              <a
                className={styles.row}
                href={entry.url}
                target="_blank"
                rel="noreferrer noopener"
                data-active={active === entry.id || undefined}
                onPointerEnter={event => { if (event.pointerType === "mouse") setActive(entry.id); }}
                onFocus={() => setActive(entry.id)}
                onBlur={() => setActive(null)}
              >
                <span className={styles.number} aria-hidden="true">{index + 1}</span>
                <SiteMark site={site} index={index} />
                <span className={styles.rowText}>
                  <span className={styles.rowTitle}>{entry.title}</span>
                  <span className={styles.rowSite}>{site}{entry.date ? ` · ${entry.date}` : ""}</span>
                </span>
                <ArrowUpRight className={styles.rowArrow} size={15} aria-hidden="true" />
              </a>
            </motion.li>
          );
        })}
      </ol>
    </section>
  );
}

export default Citations;

.root { display: flex; min-width: 0; flex-direction: column; gap: var(--space-5); color: var(--foreground); font-family: var(--font-body); font-size: var(--text-base); letter-spacing: var(--tracking-body); line-height: 1.65; }
.root p { margin: 0; }

.joint { white-space: nowrap; }
/* The chip sits in the line like a superscript without stretching the line height. */
.chip { position: relative; top: -.12em; display: inline-grid; min-width: 1.5em; height: 1.5em; place-items: center; margin: 0 .06em 0 .18em; padding: 0 .4em; border: 0; border-radius: var(--radius-pill); background: var(--surface-muted); color: var(--text-secondary); font: inherit; font-size: .72em; font-variant-numeric: tabular-nums; font-weight: 600; line-height: 1; vertical-align: baseline; cursor: pointer; -webkit-tap-highlight-color: transparent; box-shadow: inset 0 0 0 1px var(--border); transition: background-color var(--duration-fast) var(--ease-standard), color var(--duration-fast) var(--ease-standard), box-shadow var(--duration-fast) var(--ease-standard), scale var(--duration-spring) var(--ease-spring); }
.chip[data-active], .chip[data-state="open"] { background: var(--accent); color: var(--accent-foreground); box-shadow: none; scale: 1.12; }
.chip:active { scale: .94; transition-duration: var(--duration-instant); }
@media (hover: hover) and (pointer: fine) { .chip:hover { background: var(--accent); color: var(--accent-foreground); box-shadow: none; } }

/* The card grows out of the chip it belongs to. */
.card { z-index: 70; display: flex; width: min(20rem, calc(100vw - var(--space-6))); flex-direction: column; gap: var(--space-2); padding: var(--space-4); border: 1px solid var(--border); border-radius: var(--radius-panel); background: var(--surface-raised); color: var(--foreground); box-shadow: var(--shadow-floating); font-family: var(--font-body); font-size: var(--text-sm); letter-spacing: var(--tracking-body); line-height: var(--leading-body); transform-origin: var(--radix-popover-content-transform-origin); outline: none; }
.card[data-state="open"] { animation: card-in var(--duration-spring) var(--ease-spring); }
.card[data-state="closed"] { animation: card-out var(--duration-fast) var(--ease-exit) forwards; }
.card[data-state="open"] > * { animation: line-in var(--duration-considered) var(--ease-enter) backwards; }
.card[data-state="open"] > :nth-child(2) { animation-delay: 50ms; }
.card[data-state="open"] > :nth-child(3) { animation-delay: 100ms; }
.cardSite { display: flex; min-width: 0; align-items: center; gap: var(--space-2); color: var(--text-secondary); font-size: var(--text-xs); }
.cardHost { overflow: hidden; font-weight: 500; text-overflow: ellipsis; white-space: nowrap; }
.cardDate { flex: none; color: var(--text-muted); }
.cardDate::before { content: "·"; margin-right: var(--space-2); }
.cardNumber { display: grid; min-width: 20px; height: 20px; flex: none; place-items: center; margin-left: auto; border-radius: var(--radius-pill); background: var(--accent); color: var(--accent-foreground); font-size: 11px; font-variant-numeric: tabular-nums; font-weight: 600; }
.cardTitle { display: inline; color: var(--foreground); font-family: var(--font-display); font-size: var(--text-base); font-weight: 600; letter-spacing: var(--tracking-display); line-height: 1.3; text-decoration: none; border-radius: 4px; }
.cardTitle svg { display: inline; margin-left: 4px; color: var(--text-muted); vertical-align: -1px; transition: translate var(--duration-fast) var(--ease-standard), color var(--duration-fast) var(--ease-standard); }
@media (hover: hover) and (pointer: fine) { .cardTitle:hover { text-decoration: underline; text-decoration-color: var(--border-strong); text-underline-offset: 3px; } .cardTitle:hover svg { color: var(--accent-strong); translate: 1px -1px; } }
.cardSnippet { display: -webkit-box; margin: 0; overflow: hidden; -webkit-box-orient: vertical; -webkit-line-clamp: 4; line-clamp: 4; color: var(--text-secondary); }

.mark { display: grid; width: 20px; height: 20px; flex: none; place-items: center; border-radius: 6px; background: color-mix(in oklab, var(--tone) 18%, transparent); color: var(--tone); font-size: 11px; font-weight: 700; line-height: 1; }

.sources { min-width: 0; }
.sourcesTitle { display: flex; align-items: center; gap: var(--space-2); margin: 0 0 var(--space-2); color: var(--text-muted); font-size: var(--text-xs); font-weight: 600; letter-spacing: .04em; text-transform: uppercase; }
.sourcesCount { display: grid; min-width: 18px; height: 18px; place-items: center; padding: 0 5px; border-radius: var(--radius-pill); background: var(--surface-muted); color: var(--text-secondary); font-variant-numeric: tabular-nums; letter-spacing: 0; }
.list { display: flex; flex-direction: column; gap: 2px; margin: 0 calc(var(--space-2) * -1); padding: 0; list-style: none; }
.item { position: relative; }
/* One shared highlight that glides between rows. */
.highlight { position: absolute; inset: 0; border-radius: var(--radius-control); background: var(--surface-muted); }
.row { position: relative; display: flex; min-width: 0; align-items: center; gap: var(--space-3); padding: var(--space-2); border-radius: var(--radius-control); color: var(--foreground); font-size: var(--text-sm); line-height: var(--leading-body); text-decoration: none; --focus-outline-offset: -2px; }
.number { display: grid; width: 22px; height: 22px; flex: none; place-items: center; border-radius: var(--radius-pill); color: var(--text-secondary); font-size: var(--text-xs); font-variant-numeric: tabular-nums; font-weight: 600; box-shadow: inset 0 0 0 1px var(--border); transition: background-color var(--duration-fast) var(--ease-standard), color var(--duration-fast) var(--ease-standard), box-shadow var(--duration-fast) var(--ease-standard); }
.row[data-active] .number { background: var(--accent); color: var(--accent-foreground); box-shadow: none; }
.rowText { display: flex; min-width: 0; flex: 1; flex-direction: column; }
.rowTitle { display: -webkit-box; overflow: hidden; -webkit-box-orient: vertical; -webkit-line-clamp: 2; line-clamp: 2; font-weight: 500; }
.rowSite { overflow: hidden; color: var(--text-muted); font-size: var(--text-xs); text-overflow: ellipsis; white-space: nowrap; }
.rowArrow { flex: none; margin-right: var(--space-1); color: var(--text-muted); opacity: 0; transform: translate(-4px, 4px); transition: opacity var(--duration-fast) var(--ease-standard), transform var(--duration-spring) var(--ease-spring); }
.row[data-active] .rowArrow { opacity: 1; transform: none; }

@keyframes card-in { from { opacity: 0; transform: translateY(6px) scale(.94); } }
@keyframes card-out { to { opacity: 0; transform: translateY(3px) scale(.97); } }
@keyframes line-in { from { opacity: 0; transform: translateY(5px); } }
@media (prefers-reduced-motion: reduce) {
  .card[data-state="open"], .card[data-state="closed"], .card[data-state="open"] > * { animation: none; }
  .chip, .number, .rowArrow, .cardTitle svg { transition: none; }
  .chip[data-active], .chip[data-state="open"], .chip:active { scale: none; }
}
